    public static Loan reconstitute(UUID id, UUID bookId, UUID memberId, LocalDate loanedAt, LocalDate dueAt,
                                    CreditCheck creditCheck, LocalDate returnedAt) {
        return new Loan(id, bookId, memberId, loanedAt, dueAt, creditCheck, returnedAt);
    }

    public void markReturned(LocalDate today) {
        if (isReturned()) {
            throw new LoanAlreadyReturnedException(id);
        }
        if (today.isBefore(loanedAt)) {
            throw new IllegalArgumentException("returnedAt must not be before loanedAt");
        }
        returnedAt = today;
    }

    public boolean isReturned() {
        return returnedAt != null;
    }

    public boolean isOverdue(LocalDate today) {
        return !isReturned() && today.isAfter(dueAt);
    }

    // 반납일 기준으로 반납 기한(dueAt)을 넘긴 일수. 기한 당일 반납까지는 0 이다.
    public long overdueDays() {
        LocalDate returned = getReturnedAt()
                .orElseThrow(() -> new IllegalStateException("loan is not returned: " + id));
        return Math.max(0, ChronoUnit.DAYS.between(dueAt, returned));
    }

    public long lateFee() {
        return overdueDays() * LATE_FEE_PER_DAY;
    }

    public UUID getId() {
        return id;
    }

    public UUID getBookId() {
        return bookId;
    }

    public UUID getMemberId() {
        return memberId;
    }

    public LocalDate getLoanedAt() {
        return loanedAt;
    }

    public LocalDate getDueAt() {
        return dueAt;
    }

    public CreditCheck getCreditCheck() {
        return creditCheck;
    }

    public Optional<LocalDate> getReturnedAt() {
        return Optional.ofNullable(returnedAt);
    }
}
