    @Test
    void sponsor_members_have_no_loan_limit_but_other_assigned_ids_do() throws Exception {
        String sponsorId = "11111111-1111-1111-1111-111111111111";
        mockMvc.perform(post("/members").contentType(MediaType.APPLICATION_JSON)
                        .content(objectMapper.writeValueAsString(new IdNameBody(sponsorId, "후원자"))))
                .andExpect(status().isCreated())
                .andExpect(jsonPath("$.memberId").value(sponsorId))
                .andExpect(jsonPath("$.name").value("후원자"));
        for (int i = 1; i <= 6; i++) {
            loanBook(registerBook("후원자 책 " + i), sponsorId);
        }
        mockMvc.perform(post("/members").contentType(MediaType.APPLICATION_JSON)
                        .content(objectMapper.writeValueAsString(new IdNameBody(sponsorId, "사칭"))))
                .andExpect(status().isConflict())
