    private String reserve(String bookId, String memberId, int expectedPosition) throws Exception {
        String response = mockMvc.perform(post("/books/{bookId}/reservations", bookId)
                        .contentType(MediaType.APPLICATION_JSON)
                        .content(memberBody(memberId)))
                .andExpect(status().isCreated())
                .andExpect(jsonPath("$.reservationId").isNotEmpty())
                .andExpect(jsonPath("$.position").value(expectedPosition))
                .andReturn().getResponse().getContentAsString();
